-- Políticas REALES de pa_docs en producción (proyecto «pa carlos»), copiadas del resultado de medicion_egress.sql. Todas para el rol authenticated.
create policy pa_del on public.pa_docs for delete to authenticated using (((pa_role() = 'admin'::text) OR ((col = 'plans'::text) AND (pa_role() = ANY (ARRAY['supervisor'::text, 'comodin'::text])) AND pa_can_del() AND (((data ->> 'region'::text) = pa_region()) OR ((pa_role() = 'supervisor'::text) AND (pa_xmode((data ->> 'region'::text)) = 'editar'::text))))));
create policy pa_enc_ins on public.pa_docs for insert to authenticated with check (((col = 'meta'::text) AND ((pa_role() = 'admin'::text) OR ((pa_role() = 'supervisor'::text) AND (id = ('enc_'::text || pa_region()))))));
create policy pa_enc_upd on public.pa_docs for update to authenticated using (((col = 'meta'::text) AND (pa_role() = 'supervisor'::text) AND (id = ('enc_'::text || pa_region())))) with check (((col = 'meta'::text) AND (pa_role() = 'supervisor'::text) AND (id = ('enc_'::text || pa_region()))));
create policy pa_ins on public.pa_docs for insert to authenticated with check (((pa_role() IS NOT NULL) AND ((pa_role() = 'admin'::text) OR ((col = 'plans'::text) AND (pa_role() = ANY (ARRAY['supervisor'::text, 'comodin'::text])) AND ((data ->> 'region'::text) = pa_region())) OR ((col = 'plans'::text) AND (pa_role() = 'sucursal'::text) AND ((data ->> 'region'::text) = pa_region()) AND ((data ->> 'branch'::text) = pa_branch()) AND ((data ->> 'type'::text) = 'Operaciones'::text) AND ((data ->> 'auto'::text) = '1'::text)) OR (col = 'notifs'::text))));
create policy pa_rev_sel on public.pa_docs for select to authenticated using (((col = 'plans'::text) AND (pa_role() = ANY (ARRAY['analista'::text, 'gerencia'::text]))));
create policy pa_rev_upd on public.pa_docs for update to authenticated using (((col = 'plans'::text) AND (pa_role() = ANY (ARRAY['analista'::text, 'gerencia'::text])))) with check (((col = 'plans'::text) AND (pa_role() = ANY (ARRAY['analista'::text, 'gerencia'::text]))));
create policy pa_sel on public.pa_docs for select to authenticated using (((pa_role() IS NOT NULL) AND ((col = ANY (ARRAY['users'::text, 'meta'::text])) OR ((col = 'plans'::text) AND ((pa_role() = ANY (ARRAY['admin'::text, 'visualizador'::text])) OR ((pa_role() = 'inventarios'::text) AND ((data ->> 'type'::text) = 'Inventarios'::text) AND (pa_inv_all() OR pa_inv_can((data ->> 'region'::text), (data ->> 'branch'::text)))) OR ((pa_role() = ANY (ARRAY['supervisor'::text, 'comodin'::text])) AND ((data ->> 'region'::text) = pa_region())) OR ((pa_role() = 'supervisor'::text) AND (pa_xmode((data ->> 'region'::text)) IS NOT NULL)) OR ((pa_role() = 'sucursal'::text) AND ((data ->> 'region'::text) = pa_region()) AND ((data ->> 'branch'::text) = pa_branch())))) OR ((col = 'notifs'::text) AND ((data -> 'to'::text) @> to_jsonb(pa_uid()))))));
create policy pa_upd on public.pa_docs for update to authenticated using (((pa_role() IS NOT NULL) AND ((pa_role() = 'admin'::text) OR ((col = 'plans'::text) AND (((pa_role() = 'inventarios'::text) AND pa_inv_rev() AND ((data ->> 'type'::text) = 'Inventarios'::text) AND (pa_inv_all() OR pa_inv_can((data ->> 'region'::text), (data ->> 'branch'::text)))) OR ((pa_role() = ANY (ARRAY['supervisor'::text, 'comodin'::text])) AND ((data ->> 'region'::text) = pa_region())) OR ((pa_role() = 'supervisor'::text) AND (pa_xmode((data ->> 'region'::text)) = 'editar'::text)) OR ((pa_role() = 'sucursal'::text) AND ((data ->> 'region'::text) = pa_region()) AND ((data ->> 'branch'::text) = pa_branch())))) OR ((col = 'notifs'::text) AND ((data -> 'to'::text) @> to_jsonb(pa_uid()))) OR ((col = 'users'::text) AND (id = pa_uid()))))) with check (((pa_role() IS NOT NULL) AND ((pa_role() = 'admin'::text) OR ((col = 'plans'::text) AND (((pa_role() = 'inventarios'::text) AND pa_inv_rev() AND ((data ->> 'type'::text) = 'Inventarios'::text) AND (pa_inv_all() OR pa_inv_can((data ->> 'region'::text), (data ->> 'branch'::text)))) OR ((pa_role() = ANY (ARRAY['supervisor'::text, 'comodin'::text])) AND ((data ->> 'region'::text) = pa_region())) OR ((pa_role() = 'supervisor'::text) AND (pa_xmode((data ->> 'region'::text)) = 'editar'::text)) OR ((pa_role() = 'sucursal'::text) AND ((data ->> 'region'::text) = pa_region()) AND ((data ->> 'branch'::text) = pa_branch())))) OR ((col = 'notifs'::text) AND ((data -> 'to'::text) @> to_jsonb(pa_uid()))) OR ((col = 'users'::text) AND (id = pa_uid())))));
